CREATE POLICY admin_papers_read ON public.exam_papers FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_scholarships_read ON public.scholarships FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.protect_class_fields() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF NEW.created_by<>OLD.created_by OR NEW.school_id IS DISTINCT FROM OLD.school_id THEN RAISE EXCEPTION 'Class ownership cannot change'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER protect_class BEFORE UPDATE ON public.classes FOR EACH ROW EXECUTE FUNCTION public.protect_class_fields();
REVOKE UPDATE ON public.class_invites FROM authenticated; GRANT UPDATE(revoked_at) ON public.class_invites TO authenticated;
CREATE FUNCTION public.assign_student_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'student') ON CONFLICT DO NOTHING; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_student_role() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER assign_student_role AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.assign_student_role();
INSERT INTO public.user_roles(user_id,role) SELECT id,'student' FROM public.profiles p WHERE NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.id) ON CONFLICT DO NOTHING;
DO $$ DECLARE p record; q text; w text; BEGIN FOR p IN SELECT * FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND (qual LIKE '%profiles p%' OR with_check LIKE '%profiles p%') LOOP q:=replace(p.qual,E'(EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND (p.role = ''admin''::text))))','public.has_role(auth.uid(),''admin'')'); w:=replace(p.with_check,E'(EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND (p.role = ''admin''::text))))','public.has_role(auth.uid(),''admin'')'); IF q LIKE '%profiles p%' OR w LIKE '%profiles p%' THEN RAISE EXCEPTION 'Unconverted storage policy'; END IF; EXECUTE format('ALTER POLICY %I ON storage.objects%s%s',p.policyname,CASE WHEN q IS NOT NULL THEN ' USING ('||q||')' ELSE '' END,CASE WHEN w IS NOT NULL THEN ' WITH CHECK ('||w||')' ELSE '' END); END LOOP; END $$;